func (s *Store) GetGuild(ctx context.Context, guildID string) (*GuildSettings, error) {
	const q = `
		SELECT guild_id, locale, prefix, antiraid_on, score_threshold,
		       default_action, log_channel_id, welcome_channel,
		       welcome_message, welcome_image_url, ai_moderation, updated_at
		FROM guilds WHERE guild_id = $1`

	var g GuildSettings
	err := s.pool.QueryRow(ctx, q, guildID).Scan(
		&g.GuildID, &g.Locale, &g.Prefix, &g.AntiraidOn, &g.ScoreThreshold,
		&g.DefaultAction, &g.LogChannelID, &g.WelcomeChannel,
		&g.WelcomeMessage, &g.WelcomeImageURL, &g.AIModeration, &g.UpdatedAt,
	)
	if errors.Is(err, pgx.ErrNoRows) {
		return nil, ErrGuildNotFound
	}
	if err != nil {
		return nil, fmt.Errorf("storage: get guild %s: %w", guildID, err)
	}
	return &g, nil
}

