func (s *Store) GetOrCreateGuild(ctx context.Context, guildID string) (*GuildSettings, error) {
	g, err := s.GetGuild(ctx, guildID)
	if err == nil {
		return g, nil
	}
	if !errors.Is(err, ErrGuildNotFound) {
		return nil, err
	}
	def := DefaultGuildSettings(guildID)
	if err := s.UpsertGuild(ctx, def); err != nil {
		return nil, err
	}
	return def, nil
}

