func (s *Store) PatchGuild(ctx context.Context, guildID string, mutate func(*GuildSettings)) (*GuildSettings, error) {
	g, err := s.GetOrCreateGuild(ctx, guildID)
	if err != nil {
		return nil, err
	}
	mutate(g)
	if err := s.UpsertGuild(ctx, g); err != nil {
		return nil, err
	}
	return g, nil
}

