func (s *Store) DeleteGuild(ctx context.Context, guildID string) error {
	if _, err := s.pool.Exec(ctx, `DELETE FROM guilds WHERE guild_id = $1`, guildID); err != nil {
		return fmt.Errorf("storage: delete guild %s: %w", guildID, err)
	}
	return nil
}

// ListGuilds devuelve guilds paginados por updated_at desc (dashboard admin).
func (s *Store) ListGuilds(ctx context.Context, limit, offset int) ([]GuildSettings, error) {
	if limit <= 0 || limit > 500 {
		limit = 50
	}
	if offset < 0 {
		offset = 0
	}
	const q = `
		SELECT guild_id, locale, prefix, antiraid_on, score_threshold,
		       default_action, log_channel_id, welcome_channel,
		       welcome_message, welcome_image_url, ai_moderation, updated_at
		FROM guilds
		ORDER BY updated_at DESC
		LIMIT $1 OFFSET $2`

	rows, err := s.pool.Query(ctx, q, limit, offset)
	if err != nil {
		return nil, fmt.Errorf("storage: list guilds: %w", err)
	}
	defer rows.Close()

	out := make([]GuildSettings, 0, limit)
	for rows.Next() {
		var g GuildSettings
		if err := rows.Scan(
			&g.GuildID, &g.Locale, &g.Prefix, &g.AntiraidOn, &g.ScoreThreshold,
			&g.DefaultAction, &g.LogChannelID, &g.WelcomeChannel,
			&g.WelcomeMessage, &g.WelcomeImageURL, &g.AIModeration, &g.UpdatedAt,
		); err != nil {
			return nil, fmt.Errorf("storage: scan guild: %w", err)
		}
		out = append(out, g)
	}
	return out, rows.Err()
}

// CountGuilds devuelve el total de guilds registrados.
func (s *Store) CountGuilds(ctx context.Context) (int64, error) {
	var n int64
	if err := s.pool.QueryRow(ctx, `SELECT COUNT(*) FROM guilds`).Scan(&n); err != nil {
		return 0, fmt.Errorf("storage: count guilds: %w", err)
	}
	return n, nil
}
